### Code Review: Runtime Metrics Protocol Exposure

**Summary:**
The `MetricsTracker` in `apps/game-runtime` correctly aggregates runtime statistics, but these are currently only persisted to disk (`StateStore`) and not exposed over the WebSocket protocol to the client HUD.

To fix this with the smallest protocol-first change set:
1.  **Protocol (`packages/protocol`)**: Add a `metrics` field to the `session.state` server message payload.
2.  **Runtime (`apps/game-runtime`)**: Inject `this.metrics.snapshot()` into the `session.state` emission.
3.  **Client (`apps/game-client`)**: Consume the metrics in the `session.state` handler and display them in the HUD.
4.  **Tests**: Update the contract test to verify the new field.

---

### 1. Protocol Definition
**File:** `packages/protocol/src/messages.ts`

Add the `RuntimeMetrics` type and include it in the `session.state` payload.

```typescript
// packages/protocol/src/messages.ts

// ... existing imports ...

// Add new type definition
export type RuntimeMetrics = {
  turnsTotal: number;
  invalidOutputCount: number;
  actionAppliedCount: number;
  actionRejectedCount: number;
  queuedActions: number;
};

// ... existing types ...

export type ServerMessage =
  | {
      version: Version;
      type: "session.state";
      payload: {
        phase: SessionPhase;
        paused: boolean;
        preparedSeed: number | null;
        threadIds: { gameplayByAgentId: Record<string, string>; builder?: string };
        connected: boolean;
        runtime: {
          model: string | null;
          effort: TurnEffort;
          tickMs: number;
          schedulerMs: number;
          maxQueuedActionsBeforeTurn: number;
          availableModels: RuntimeModelOption[];
        };
        // ADD THIS BLOCK
        metrics: RuntimeMetrics;
      };
    }
  // ... rest of ServerMessage union ...
```

---

### 2. Runtime Server Implementation
**File:** `apps/game-runtime/src/runtime/GameRuntimeServer.ts`

Update `sendSessionState` to include the metrics snapshot.

```typescript
// apps/game-runtime/src/runtime/GameRuntimeServer.ts

// ... existing imports ...

private sendSessionState(): void {
  this.emitMessage({
    version: PROTOCOL_VERSION,
    type: "session.state",
    payload: {
      phase: this.phase,
      paused: this.paused,
      preparedSeed: this.preparedSeed,
      threadIds: this.threadIds,
      connected: this.connected,
      runtime: {
        model: this.turnModel,
        effort: this.turnEffort,
        tickMs: runtimeConfig.tickMs,
        schedulerMs: runtimeConfig.schedulerMs,
        maxQueuedActionsBeforeTurn: runtimeConfig.maxQueuedActionsBeforeTurn,
        availableModels: this.availableModels
      },
      // ADD THIS LINE
      metrics: this.metrics.snapshot()
    }
  });
}
```

---

### 3. Client HUD Integration
**File:** `apps/game-client/src/App.tsx`

1.  Import the new type.
2.  Add state for metrics.
3.  Update the `session.state` message handler.
4.  Display metrics in the top bar.

```typescript
// apps/game-client/src/App.tsx

// 1. Update Import
import type { RuntimeModelOption, RuntimeMetrics, ServerMessage, SessionPhase, WorldNearbyEntity } from "@codexgame/protocol";

// ... inside App component ...

// 2. Add State
const [runtimeMetrics, setRuntimeMetrics] = useState<RuntimeMetrics>({
  turnsTotal: 0,
  invalidOutputCount: 0,
  actionAppliedCount: 0,
  actionRejectedCount: 0,
  queuedActions: 0
});

// ... inside ws.onmessage effect ...

case "session.state":
  setPhase(message.payload.phase);
  setPaused(message.payload.paused);
  setPreparedSeed(message.payload.preparedSeed);
  setThreadIds(message.payload.threadIds);
  setRuntimeModel(message.payload.runtime.model);
  setRuntimeEffort(message.payload.runtime.effort);
  setRuntimeSchedulerMs(message.payload.runtime.schedulerMs);
  setRuntimeQueueAhead(message.payload.runtime.maxQueuedActionsBeforeTurn);
  setAvailableModels(message.payload.runtime.availableModels);

  // 3. Update Handler
  if (message.payload.metrics) {
    setRuntimeMetrics(message.payload.metrics);
  }

  if (message.payload.phase === "idle") {
    setTick(0);
    setRuntimeAgents([]);
    setCatalog({ prefabs: [], recipes: [] });
    sceneRef.current?.clearSnapshot();
  }
  return;

// ... inside return JSX ...

<div className="game-topbar">
  <span className="pill">Runtime: {connected ? "connected" : "offline"}</span>
  <span className="pill">Phase: {phase}</span>
  <span className="pill">Latency: {latencyMs}ms</span>
  <span className="pill">Model: {runtimeModel ?? "default"}</span>
  <span className="pill">
    Effort: {runtimeEffort} | Scheduler: {runtimeSchedulerMs || "-"}ms
  </span>
  {/* 4. Add Metrics Display */}
  <span className="pill">
    Turns: {runtimeMetrics.turnsTotal} | Applied: {runtimeMetrics.actionAppliedCount} | Rejected: {runtimeMetrics.actionRejectedCount}
  </span
